def sim(cells,dx_,dy_):
    cur=set(cells); k=0
    while True:
        nxt={(y+dy_,x+dx_) for y,x in cur}
        if any(not(0<=yy<17 and 0<=xx<7) for yy,xx in nxt): break
        # touching if adjacent to any other cell
        adj=False
        for yy,xx in nxt:
            for a,b in others:
