    mv=[v for v,s_ in ncomp_by_color.items() if len(s_)>=2][0]
    # recolor: marker cells take the comp's other color
    def comp_cells(c):
        ot=[v for v in {gi[y][x] for y,x in c} if v!=mv][0]
        return [(y,x, ot if gi[y][x]==mv else gi[y][x]) for y,x in c]
    order=sorted(range(len(cs)),key=lambda i:min(y for y,x in cs[i]))
    results=[]
    def bt(i,placed):
        if i==len(order):
            out=[[bg]*W for _ in range(H)]
            for p,v in placed: out[p[0]][p[1]]=v
            return out==go
        c=cs[order[i]]
        cells=comp_cells(c) if mv in {gi[y][x] for y,x in c} else None
        if mv in {gi[y][x] for y,x in c}:
            # recolor marker
            pass
        opts=[]
        if allow_tf:
            cands=[(nm,f) for nm,f in MAPS.items()]
        else:
            cands=[('id',lambda r,c:(r,c))]
