            for p,v in plist: placed.add((p,v))
            if bt(i+1,placed): results.append((nm,plist[:]))
            for p,v in plist: placed.discard((p,v))
        return bool(results)
    bt(0,set())
    print(pn,'mv',mv,'solutions:',len(results), results[:1] if results else '')
